    [Fact]
    public void Decodes_pil_jpeg_within_tolerance()
    {
        var r = JpegDecoder.Decode(Jpeg);
        Assert.True(r.Success, r.Error);
        Assert.Equal(8, r.Width);
        Assert.Equal(8, r.Height);
        Assert.Equal(Expected.Length, r.Rgb.Length);
        int maxDiff = 0;
        for (int i = 0; i < Expected.Length; i++) maxDiff = Math.Max(maxDiff, Math.Abs(r.Rgb[i] - Expected[i]));
        Assert.True(maxDiff <= 3, $"最大像素差 {maxDiff} 应≤3(IDCT/舍入差); 首像素 got=({r.Rgb[0]},{r.Rgb[1]},{r.Rgb[2]}) exp=({Expected[0]},{Expected[1]},{Expected[2]})");
    }

